"""Generate the true Phase86 report, guarded by the original window."""
from __future__ import annotations
import datetime as dt, hashlib, json, os, subprocess, tempfile
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path: sys.path.insert(0,str(ROOT))
from src.iclr27_phase86.execution_policy import assert_finalization_allowed, remaining_seconds
OUT=ROOT/'outputs/iclr27_phase86'; DOC=ROOT/'docs/iclr27_phase86/PHASE86_AUTONOMOUS_RESEARCH_REPORT.md'
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''):h.update(b)
 return h.hexdigest()
def load(p): return json.loads(p.read_text(encoding='utf-8'))
def atom(p,v):
 p.parent.mkdir(parents=True,exist_ok=True);fd,t=tempfile.mkstemp(prefix='.'+p.name+'.',dir=str(p.parent))
 try:
  with os.fdopen(fd,'w') as f:json.dump(v,f,indent=2,sort_keys=True,allow_nan=False);f.write('\n');f.flush();os.fsync(f.fileno())
  os.replace(t,p)
 finally:
  if os.path.exists(t):os.unlink(t)
def metric_summary(path, prefix=16):
 if not path.exists(): return {}
 o=load(path)
 values=o.get('summary',[]) or o.get('aggregate',[])
 return next((x.get('aggregate',x) for x in values if x.get('prefix')==prefix),{})
def main():
 assert_finalization_allowed()
 reg=load(OUT/'audit/window_registration.json'); resume=load(OUT/'audit/resume_after_premature_finalization.json'); d=load(OUT/'audit/diagnostic_ocd_full_metrics.json'); u1=load(OUT/'metrics/u1_final_alltrain_event_v3.json'); rf=load(OUT/'metrics/rf_canonical_root_v2.json'); u2=load(OUT/'audit/u2_decision.json'); methods=load(OUT/'audit/recent_method_audit.json'); ledger=load(OUT/'audit/research_ledger.json');
 u1p=[x for x in u1['summary'] if x['prefix']==16 and x['polarity']=='positive'][0]; u1n=[x for x in u1['summary'] if x['prefix']==16 and x['polarity']=='negative'][0]; rfp=metric_summary(OUT/'metrics/rf_canonical_root_v2.json'); head=subprocess.run(['git','rev-parse','HEAD'],cwd=ROOT,text=True,capture_output=True,check=True).stdout.strip()
 decision={'schema_version':'trackocd.phase86.decision.v3','phase':86,'status':'PHASE86_WINDOW_COMPLETE_WITH_VALID_NEGATIVE_EVIDENCE','finalization_unlocked':True,'original_window':{'start_utc':reg['start_utc'],'deadline_utc':reg['deadline_utc']},'premature_report_corrected':True,'u1_final_event':{'positive_p16':u1p,'negative_p16':u1n,'status':'U1_FINAL_EVENT_SAFETY_FAIL'},'rf_canonical_root':{'p16':rfp,'decision':rf.get('decision')},'u2':u2,'controller_run':False,'formal_ocd_run':False,'sealed_run':False,'public_dev_q1_sealed_accessed':False,'next_action':'No controller or sealed claim; preserve legal negative evidence and await a new registered support contract.'}
 atom(OUT/'audit/phase86_decision.json',decision);atom(OUT/'status.json',decision)
 lines=['# TrackOCD Phase86 — Autonomous Research Report (final window snapshot)','',f'**Status:** `{decision["status"]}`  ',f'**Generated (UTC):** `{dt.datetime.now(dt.timezone.utc).isoformat()}`  ',f'**Original window:** `{reg["start_utc"]}` → `{reg["deadline_utc"]}`  ',f'**Remaining at generation:** `{remaining_seconds():.0f}s`  ','','> The earlier report was an interim premature snapshot. This report was generated only after the registered deadline-minus-45-minute unlock.','', '## 1. Execution repair and provenance','',f'- Original registration was not rerun. Resume record: `{(OUT/"audit/resume_after_premature_finalization.json").resolve()}`.','- The finalization guard rejects early generation and allows only the registered unlock interval or an explicit allowed hard blocker. No hard blocker was declared.','- Code/contract repair head before final report: `'+head+'`; original premature report head: `'+resume['premature_report_head']+'`.','- Old D0/D1/U1/RF artifacts remain read-only evidence. The old modulo-3 event replay is labeled `U1_CV_CHECKPOINT_ROUTING_EVENT_DIAGNOSTIC`; the old within-track chunks are `WITHIN_TRACK_4FRAME_CHUNK_DIAGNOSTIC_NEGATIVE`.','- GPU0 PID 33785 and external intermot workers were not touched. CPU routes used bounded single-process execution; no OOM or broad kill occurred. `/data1` was nearly full, so large outputs/checkpoints remained on `/data2` via the existing symlink.','', '## 2. Frozen boundaries','', '- No DEV+, Q1, public-new or sealed labels were used for training, checkpoint selection or inference. No future rows/tracks, category text, semantic IDs or physical IDs entered model tensors.','- The Phase19R controller/StateMemory, event denominator (76 positive + 76 negative), prefixes `{1,2,4,8,16}`, candidate metadata order and frozen manifests were not changed.','- Formal controller, Commit-CT and sealed evaluation were not run because no corrected score route passed its upstream safety gate.','', '## 3. Frozen D0/D1 diagnostic OCD','', '| stream | Commit-CT | existing F1 macro | negative false-merge | unresolved | premature | duplicate births | category/video coverage |','|---|---:|---:|---:|---:|---:|---:|---|']
 for name,label in [('D0_historical_Q0_RCMSOCD','D0 historical Q0 + frozen RC-MS-OCD'),('D1_temporal_physical_RCMSOCD','D1 temporal physical + frozen RC-MS-OCD')]:
  s=d['streams'][name]; a=s['aggregate']; c=s['aggregate_commit_ct']; lines.append(f"| {label} | {c['correct']}/{c['eligible']} | {a['existing_f1_macro']:.4f} | {a['negative_false_merge_rate']:.4f} | {a['unresolved_rate']:.4f} | {a['premature_rate']:.4f} | {a['duplicate_births']} | category={a['category_coverage']}, video={a['video_coverage']} |")
 lines += ['', 'D0 and D1 both remain diagnostic-only 3/76, all three correct events in fold3. The full metric artifact is `audit/diagnostic_ocd_full_metrics.json`; no D0/D1 replay was repeated during resume.','', '## 4. Corrected all-TRAIN U1 deployment','', '| route | p16 positive | p16 negative | reranker-use positive | reranker-use negative | decision |','|---|---:|---:|---:|---:|---|',f"| corrected all-TRAIN expert + all-OOF gate | {u1p['final_reliable_events']}/76 | {u1n['final_reliable_events']}/76 | {u1p['events_using_reranker']}/76 | {u1n['events_using_reranker']}/76 | **U1_FINAL_EVENT_SAFETY_FAIL** |",'', 'The support expert used the validated 19-D/10-D `SupportReranker`, 15 effective epochs, 54,780 steps and seed 86001. The gate used the unchanged 64→32 utility architecture, 2,000 steps and seed 86100. The two checkpoint paths and hashes are embedded in the replay artifact. Model selection never used event labels; event fold is reporting only, not model routing. The registered safety rule (positive≥22/76 and negative≤8/76) was not met.','', '## 5. Canonical-root RF','',f"- Source lineage: `{rf['root_reconstruction']['lineage']}`; union timeline: `{rf['root_reconstruction']['union_events']}`.",f"- Reconstructed comparisons: `{rf['root_reconstruction']['root_comparisons']}`; fraction roots with >1 fragment: `{rf['root_reconstruction']['fraction_roots_gt1_fragment']:.4f}`; maximum fragments: `{rf['root_reconstruction']['max_fragments_per_root']}`; fallback comparisons: `{rf['root_reconstruction']['fallback_count']}`.",f"- p16 raw R@1/mAP `{rfp.get('raw_r1',0):.6f}/{rfp.get('raw_map',0):.6f}`; canonical-root `{rfp.get('r1',0):.6f}/{rfp.get('map',0):.6f}`; unsafe flips `{rfp.get('unsafe_flip_count',0)}`; non-decreasing folds `{rf.get('p16_non_decreasing_folds')}/4`.",'- Decision: `RF_CANONICAL_ROOT_V1_NEGATIVE`. It is a valid canonical-root test, not the old within-track diagnostic, and it does not authorize the controller.','', '## 6. U2 and recent-method audit','',f"- U2-v1 three-fold TRAIN validation produced zero rescue and zero harm in every fold; raw top-1/top-5 were unchanged and the learned residual saturated to a constant. Decision: `{u2['status']}`.", '- One minimal repair balanced match/defer exposure without changing architecture, candidates, seed or protocol. It also produced zero rescue/harm in all folds. No third U2 variant was launched.','- The verified recent audit covers AGE, TALON, LTC, TRACT, COVTrack, ObjectRelator and C3Po with current remote heads and license status. None exposes a drop-in text-free causal prior-support selector for this schema, so no external code/weights were imported. See `docs/iclr27_phase86/RECENT_METHOD_AUDIT.md`.','', '## 7. Gate/status table','', '| gate | result | interpretation |','|---|---|---|','| frozen D0/D1 | diagnostic 3/76 | controller baseline evidence only |','| corrected U1 event safety | FAIL | 20/76 positive, 12/76 negative |','| canonical-root RF | FAIL | 2/4 non-decreasing and one unsafe flip |','| U2 TRAIN | FAIL | 0/3 folds with net rescue |','| controller/formal OCD | NOT RUN | no legal safe upstream stream |','| sealed/public | NOT RUN | sealed boundary preserved |','', '## 8. Reproduction','', '```bash', 'cd /data1/LWR/vranlee/SERVER_ONLY/avis/OCD_OVMOT', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/train_support_expert_final.py', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/train_u1_final.py', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_u1_final_event_replay.py --tag u1_final_alltrain_event_v3', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/run_rf_canonical_root.py --tag rf_canonical_root_v2', '/home/lwr/anaconda3/envs/locatemot/bin/python scripts/iclr27_phase86/train_u2.py --mode cv --fold 0 --epochs 15 --steps 1000', '```','', '## 9. Final research decision','', '**Phase86 did not complete MOT+OCD or sealed evaluation.** The resume corrected the deployment and execution contracts and exhausted the registered U1, canonical-root RF, U2-v1 and one justified U2 balancing repair. The evidence supports a narrower conclusion: current Phase85 support supervision/selector interface does not yield a safe upstream candidate under the frozen protocol. It is not evidence that the entire TrackOCD task is universally impossible. A future phase must register a new legal support contract or materially improve supervision; it must not repeat fold-modulo deployment, within-track RF chunks, or another gate/threshold lottery.','', '## 10. Artifact provenance','',f"- Decision: `{(OUT/'audit/phase86_decision.json').resolve()}`",f"- Ledger: `{(OUT/'audit/research_ledger.json').resolve()}`",f"- U1 replay: `{(OUT/'metrics/u1_final_alltrain_event_v3.json').resolve()}`",f"- RF replay: `{(OUT/'metrics/rf_canonical_root_v2.json').resolve()}`",f"- U2 decision: `{(OUT/'audit/u2_decision.json').resolve()}`",f"- Source code head: `{head}`",'- `public_dev_q1_sealed_accessed=false`, `formal_ocd_run=false`, `sealed_run=false`.']
 DOC.parent.mkdir(parents=True,exist_ok=True); tmp=DOC.with_name('.'+DOC.name+'.tmp'); tmp.write_text('\n'.join(lines)+'\n',encoding='utf-8'); os.replace(tmp,DOC)
 prov={'schema_version':'trackocd.phase86.report_provenance.v2','phase':86,'status':decision['status'],'generated_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'report':str(DOC.resolve()),'report_sha256':sha(DOC),'decision':str((OUT/'audit/phase86_decision.json').resolve()),'decision_sha256':sha(OUT/'audit/phase86_decision.json'),'start_head':reg['start_head'],'science_head':head,'report_generation_head':head,'final_head':head,'public_dev_q1_sealed_accessed':False,'formal_ocd_run':False,'sealed_run':False}
 atom(OUT/'audit/report_provenance.json',prov); print(json.dumps(prov,indent=2,sort_keys=True))
if __name__=='__main__':main()
